def make_counter(start=0, step=1):
    value = start - step
    def next_value():
        nonlocal value
        value += step
        return value
    return next_value


def make_averager():
    values = []
    def add(x):
        values.append(x)
        return sum(values) / len(values)
    return add


def memoize(func):
    cache = {}
    def wrapper(arg):
        if arg not in cache:
            wrapper.calls += 1
            cache[arg] = func(arg)
        return cache[arg]
    wrapper.calls = 0
    return wrapper
